import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { animalService, milkService, financeService, tasksService as taskService } from '../services/api';
import {
  AreaChart, Area,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { PawPrint, Droplets, Wallet, ClipboardList, TrendingUp, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import toast from 'react-hot-toast';

function StatCard({ label, value, sub, gradient, icon: Icon, onClick, trend, trendLabel }) {
  return (
    <button
      onClick={onClick}
      className="card-stat animate-scale-in"
      style={{ background: gradient, color: 'white' }}
    >
      <div className="flex items-start justify-between relative z-10">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium opacity-80">{label}</p>
          <p className="stat-value mt-1 text-white">{value}</p>
          {sub && <p className="text-xs mt-1.5 opacity-70">{sub}</p>}
          {trend !== undefined && (
            <div className="flex items-center gap-1 mt-2 text-xs font-semibold opacity-90">
              {trend >= 0 ? <ArrowUpRight className="w-3.5 h-3.5" /> : <ArrowDownRight className="w-3.5 h-3.5" />}
              <span>{trend > 0 ? '+' : ''}{trend}%</span>
              {trendLabel && <span className="opacity-70 font-normal">{trendLabel}</span>}
            </div>
          )}
        </div>
        {Icon && (
          <div className="p-2 rounded-xl bg-white/20 backdrop-blur-sm flex-shrink-0">
            <Icon className="w-6 h-6" />
          </div>
        )}
      </div>
    </button>
  );
}

function CustomTooltip({ active, payload, label }) {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/90 backdrop-blur-md border border-gray-200 rounded-xl shadow-lg p-3 text-sm">
        <p className="text-gray-500 font-medium mb-1">Tarih: {label}</p>
        <p className="text-teal-700 font-bold">{parseFloat(payload[0].value).toFixed(1)} L</p>
      </div>
    );
  }
  return null;
}

export default function DashboardPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const farmId = user?.farm_id;

  const [animals, setAnimals] = useState({ total: 0, goats: 0, sheep: 0, cattle: 0, buffalo: 0, camel: 0, active: 0 });
  const [milkSummary, setMilkSummary] = useState(null);
  const [financeSummary, setFinanceSummary] = useState(null);
  const [tasks, setTasks] = useState([]);
  const [milkChart, setMilkChart] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadAll = useCallback(async () => {
    if (!farmId) return;
    setLoading(true);
    try {
      const [animalRes, milkRes, financeRes, taskRes] = await Promise.allSettled([
        animalService.stats(farmId),
        milkService.summary(farmId),
        financeService.summary(farmId),
        taskService.upcoming(farmId, { days: 7 })
      ]);

      if (animalRes.status === 'fulfilled') {
        setAnimals(animalRes.value.data);
      }
      if (milkRes.status === 'fulfilled') {
        const d = milkRes.value.data;
        setMilkSummary(d);
        setMilkChart(d.daily?.slice(-14) || []);
      }
      if (financeRes.status === 'fulfilled') {
        setFinanceSummary(financeRes.value.data);
      }
      if (taskRes.status === 'fulfilled') {
        setTasks(taskRes.value.data.data || []);
      }
    } catch (err) {
      toast.error('Veriler yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId]);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  const priorityColor = { low: 'badge badge-info', medium: 'badge badge-warning', high: 'badge badge-danger', critical: 'badge badge-danger' };
  const priorityLabel = { low: 'Düşük', medium: 'Orta', high: 'Yüksek', critical: 'Kritik' };

  if (loading) return (
    <div className="flex items-center justify-center h-[60vh]">
      <div className="flex flex-col items-center gap-3">
        <div className="w-10 h-10 border-[3px] border-teal-600 border-t-transparent rounded-full animate-spin" />
        <p className="text-sm" style={{ color: 'var(--text-muted)' }}>Veriler yükleniyor...</p>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between animate-fade-in">
        <div>
          <h1 style={{ color: 'var(--text)' }}>
            Merhaba, {user?.full_name || user?.fullName || 'Kullanıcı'} 👋
          </h1>
          <p className="text-sm mt-1" style={{ color: 'var(--text-secondary)' }}>
            Bugün çiftliğinizin durumu
          </p>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-2 rounded-xl bg-teal-50 border border-teal-200">
          <TrendingUp className="w-4 h-4 text-teal-600" />
          <span className="text-sm font-medium text-teal-700">Aktif</span>
        </div>
      </div>

      {/* Stat kartları */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Toplam Hayvan"
          value={animals.total}
          sub={`${animals.active} aktif kayıt`}
          gradient="linear-gradient(135deg, #0d9488 0%, #059669 100%)"
          icon={PawPrint}
          onClick={() => navigate('/animals')}
          trend={12}
          trendLabel="geçen aya göre"
        />
        <StatCard
          label="Bugün Süt (L)"
          value={Number(milkSummary?.daily && milkSummary.daily.length > 0 ? milkSummary.daily[milkSummary.daily.length - 1]?.total : 0).toFixed(1)}
          sub={`Aylık ort: ${Number(milkSummary?.avg_daily || 0).toFixed(1)} L/gün`}
          gradient="linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)"
          icon={Droplets}
          onClick={() => navigate('/milk')}
        />
        <StatCard
          label="Bu Ay Gelir"
          value={financeSummary ? `₺${financeSummary.income.toLocaleString('tr-TR')}` : '—'}
          sub={`Gider: ₺${financeSummary?.expense?.toLocaleString('tr-TR') || 0}`}
          gradient="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)"
          icon={Wallet}
          onClick={() => navigate('/finance')}
        />
        <StatCard
          label="Açık Görev"
          value={tasks.length}
          sub="Bu hafta içinde"
          gradient="linear-gradient(135deg, #ef4444 0%, #dc2626 100%)"
          icon={ClipboardList}
          onClick={() => navigate('/tasks')}
        />
      </div>

      {/* Grafik + Görevler */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Süt Grafiği */}
        <div className="card lg:col-span-2 animate-fade-in">
          <div className="flex items-center justify-between mb-6">
            <h3 style={{ color: 'var(--text)' }}>Süt Üretimi (L)</h3>
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-teal-500" />
              <span className="text-xs font-medium" style={{ color: 'var(--text-secondary)' }}>Son 14 gün</span>
            </div>
          </div>
          {milkChart.length > 0 ? (
            <div className="animate-scale-in">
              <ResponsiveContainer width="100%" height={260}>
                <AreaChart data={milkChart}>
                  <defs>
                    <linearGradient id="milkGrad" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#0d9488" stopOpacity={0.3} />
                      <stop offset="100%" stopColor="#0d9488" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
                  <XAxis 
                    dataKey="record_date" 
                    tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
                    tickFormatter={d => d?.slice(5)}
                    axisLine={false}
                    tickLine={false}
                  />
                  <YAxis 
                    tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
                    axisLine={false}
                    tickLine={false}
                    width={40}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Area 
                    type="monotone" 
                    dataKey="total" 
                    stroke="#0d9488" 
                    strokeWidth={2.5}
                    fill="url(#milkGrad)" 
                    dot={{ fill: '#0d9488', stroke: 'white', strokeWidth: 2, r: 4 }}
                    activeDot={{ fill: '#0d9488', stroke: 'white', strokeWidth: 2, r: 6 }}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="h-64 flex items-center justify-center" style={{ color: 'var(--text-muted)' }}>
              <div className="text-center">
                <div className="text-5xl mb-3">🥛</div>
                <p className="font-medium">Henüz süt kaydı yok</p>
                <button onClick={() => navigate('/milk')} className="mt-3 btn-primary text-sm">
                  Süt kaydı ekle →
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Yaklaşan Görevler */}
        <div className="card animate-fade-in">
          <div className="flex items-center justify-between mb-5">
            <h3 style={{ color: 'var(--text)' }}>Yaklaşan Görevler</h3>
            <button onClick={() => navigate('/tasks')} className="btn-ghost text-xs">
              Tümü →
            </button>
          </div>

          {tasks.length === 0 ? (
            <div className="text-center py-10" style={{ color: 'var(--text-muted)' }}>
              <div className="text-4xl mb-3">✅</div>
              <p className="text-sm font-medium">Bu hafta görev yok</p>
            </div>
          ) : (
            <ul className="space-y-2">
              {tasks.slice(0, 6).map((task, i) => (
                <li 
                  key={task.id} 
                  className="flex items-start gap-3 p-3 rounded-xl transition-all hover:bg-gray-50 animate-slide-in"
                  style={{ 
                    animationDelay: `${i * 50}ms`,
                    animationFillMode: 'both'
                  }}
                >
                  <span className={priorityColor[task.priority]}>
                    {priorityLabel[task.priority]}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold truncate" style={{ color: 'var(--text)' }}>
                      {task.title}
                    </p>
                    <p className="text-xs mt-0.5" style={{ color: 'var(--text-muted)' }}>
                      {task.due_date}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          )}

          <div className="mt-4 pt-4" style={{ borderTop: '1px solid var(--border-light)' }}>
            <button 
              onClick={() => navigate('/tasks')}
              className="btn-primary w-full text-sm"
            >
              Yeni Görev Oluştur
            </button>
          </div>
        </div>
      </div>

      {/* Kar/Zarar özeti */}
      {financeSummary && (
        <div className="card animate-fade-in">
          <div className="flex items-center justify-between mb-6">
            <h3 style={{ color: 'var(--text)' }}>Bu Ay Mali Özet</h3>
            <button onClick={() => navigate('/finance')} className="btn-ghost text-xs">
              Tümü →
            </button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="p-5 rounded-xl" style={{ backgroundColor: 'rgba(13, 148, 136, 0.08)' }}>
              <p className="text-xs font-medium" style={{ color: 'var(--text-secondary)' }}>Gelir</p>
              <p className="stat-value mt-1" style={{ color: '#0d9488' }}>
                ₺{financeSummary.income.toLocaleString('tr-TR')}
              </p>
              <div className="flex items-center gap-1 mt-2 text-xs font-medium text-teal-600">
                <ArrowUpRight className="w-3.5 h-3.5" />
                <span>+{Math.round((financeSummary.income / (financeSummary.expense || 1)) * 100)}%</span>
              </div>
            </div>
            <div className="p-5 rounded-xl" style={{ backgroundColor: 'rgba(239, 68, 68, 0.08)' }}>
              <p className="text-xs font-medium" style={{ color: 'var(--text-secondary)' }}>Gider</p>
              <p className="stat-value mt-1" style={{ color: '#ef4444' }}>
                ₺{financeSummary.expense.toLocaleString('tr-TR')}
              </p>
              <div className="flex items-center gap-1 mt-2 text-xs font-medium text-red-500">
                <ArrowDownRight className="w-3.5 h-3.5" />
                <span>Gider</span>
              </div>
            </div>
            <div className="p-5 rounded-xl" style={{ 
              backgroundColor: financeSummary.profit >= 0 ? 'rgba(59, 130, 246, 0.08)' : 'rgba(249, 115, 22, 0.08)'
            }}>
              <p className="text-xs font-medium" style={{ color: 'var(--text-secondary)' }}>Kar / Zarar</p>
              <p className="stat-value mt-1" style={{ 
                color: financeSummary.profit >= 0 ? '#3b82f6' : '#f97316'
              }}>
                {financeSummary.profit >= 0 ? '+' : ''}₺{financeSummary.profit.toLocaleString('tr-TR')}
              </p>
              <div className="flex items-center gap-1 mt-2 text-xs font-medium" style={{
                color: financeSummary.profit >= 0 ? '#3b82f6' : '#f97316'
              }}>
                {financeSummary.profit >= 0 ? <ArrowUpRight className="w-3.5 h-3.5" /> : <ArrowDownRight className="w-3.5 h-3.5" />}
                <span>{financeSummary.profit >= 0 ? 'Karda' : 'Zararda'}</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <div className="text-center text-xs pt-6 pb-2" style={{ color: 'var(--text-muted)' }}>
        mFk Farm v1.0.0 &copy; 2026 Tüm hakları saklıdır.
      </div>
    </div>
  );
}
